-- Fixed synthetic v12-compatible schema snapshot. No user data or credentials.
-- Captured once from migrations through v12; never generated by the rehearsal.
CREATE TABLE account_credentials (
      account_id TEXT NOT NULL REFERENCES media_accounts(id) ON DELETE CASCADE,
      credential_kind TEXT NOT NULL,
      secret_id TEXT NOT NULL REFERENCES credential_secrets(id) ON DELETE CASCADE,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      PRIMARY KEY (account_id, credential_kind)
    );
CREATE TABLE account_profiles (
      account_id TEXT PRIMARY KEY REFERENCES media_accounts(id) ON DELETE CASCADE,
      positioning TEXT NOT NULL DEFAULT '',
      target_audience TEXT NOT NULL DEFAULT '',
      prohibited_topics TEXT NOT NULL DEFAULT '',
      writing_style TEXT NOT NULL DEFAULT '',
      regular_columns TEXT NOT NULL DEFAULT '',
      article_signature TEXT NOT NULL DEFAULT '',
      updated_at TEXT NOT NULL,
      fiftyone_cto_pid_options TEXT NOT NULL DEFAULT '',
      fiftyone_cto_cate_options TEXT NOT NULL DEFAULT '',
      -- 51CTO 的「授权分类」随「一级栏目」联动：这里按 pid 分组保存
      -- { "<pid>": [{value,label}...] }，切换一级栏目时只展示对应分组。
      fiftyone_cto_cate_options_by_pid TEXT NOT NULL DEFAULT ''
    , cnblogs_categories TEXT NOT NULL DEFAULT '', cnblogs_tags TEXT NOT NULL DEFAULT '');
CREATE TABLE account_style_profile_active (
        account_id TEXT PRIMARY KEY REFERENCES media_accounts(id) ON DELETE CASCADE,
        version_id TEXT NOT NULL,
        FOREIGN KEY(account_id, version_id) REFERENCES account_style_profile_versions(account_id, id)
      );
CREATE TABLE account_style_profile_proposals (
        id TEXT PRIMARY KEY,
        account_id TEXT NOT NULL REFERENCES media_accounts(id) ON DELETE CASCADE,
        profile_json TEXT NOT NULL,
        sample_sources_json TEXT NOT NULL,
        based_on_version_id TEXT,
        status TEXT NOT NULL CHECK(status IN ('pending', 'confirmed', 'rejected')),
        created_at TEXT NOT NULL,
        resolved_at TEXT
      );
CREATE TABLE account_style_profile_versions (
        id TEXT PRIMARY KEY,
        account_id TEXT NOT NULL REFERENCES media_accounts(id) ON DELETE CASCADE,
        version_number INTEGER NOT NULL CHECK(version_number > 0),
        profile_json TEXT NOT NULL,
        sample_sources_json TEXT NOT NULL,
        confirmed_at TEXT NOT NULL,
        UNIQUE(account_id, version_number),
        UNIQUE(account_id, id)
      );
CREATE TABLE account_style_samples (
        account_id TEXT NOT NULL REFERENCES media_accounts(id) ON DELETE CASCADE,
        source_relative_path TEXT NOT NULL,
        attribution_basis TEXT NOT NULL CHECK(attribution_basis IN ('published_record', 'author_confirmed')),
        selected_at TEXT NOT NULL,
        PRIMARY KEY (account_id, source_relative_path)
      );
CREATE TABLE agent_events (
      id TEXT PRIMARY KEY,
      scope_key TEXT NOT NULL,
      event_type TEXT NOT NULL,
      payload_json TEXT NOT NULL,
      created_at TEXT NOT NULL,
      expires_at TEXT
    );
CREATE TABLE agent_memories (
      id TEXT PRIMARY KEY,
      scope_key TEXT NOT NULL,
      kind TEXT NOT NULL,
      content TEXT NOT NULL,
      content_hash TEXT NOT NULL,
      source_event_ids_json TEXT NOT NULL DEFAULT '[]',
      status TEXT NOT NULL DEFAULT 'active',
      confidence REAL NOT NULL DEFAULT 0,
      importance REAL NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      last_used_at TEXT,
      recall_count INTEGER NOT NULL DEFAULT 0,
      expires_at TEXT,
      conflict_group TEXT,
      superseded_by TEXT
    );
CREATE TABLE agent_permission_grants (
      id TEXT PRIMARY KEY,
      scope TEXT NOT NULL CHECK(scope IN ('global', 'project', 'run')),
      decision TEXT NOT NULL CHECK(decision IN ('allow', 'ask', 'deny')),
      tool_id TEXT,
      action TEXT,
      project_id TEXT REFERENCES content_projects(id) ON DELETE CASCADE,
      target_prefix TEXT,
      expires_at TEXT,
      created_at TEXT NOT NULL
    );
CREATE TABLE agent_tool_workflows (
      id TEXT PRIMARY KEY,
      project_id TEXT REFERENCES content_projects(id) ON DELETE SET NULL,
      context_key TEXT NOT NULL,
      input_json TEXT NOT NULL DEFAULT '{}',
      status TEXT NOT NULL,
      round INTEGER NOT NULL DEFAULT 0,
      user_request TEXT NOT NULL,
      transcript_json TEXT NOT NULL DEFAULT '[]',
      events_json TEXT NOT NULL DEFAULT '[]',
      tool_results_json TEXT NOT NULL DEFAULT '[]',
      pending_permission_json TEXT NOT NULL DEFAULT 'null',
      final_text TEXT,
      warning_count INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE app_credentials (
      credential_kind TEXT PRIMARY KEY,
      secret_id TEXT NOT NULL REFERENCES credential_secrets(id) ON DELETE CASCADE,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE article_chat_messages (
      id TEXT PRIMARY KEY,
      context_key TEXT NOT NULL REFERENCES article_chat_threads(context_key) ON DELETE CASCADE,
      role TEXT NOT NULL CHECK(role IN ('user', 'assistant')),
      content TEXT NOT NULL,
      memory_suggestion TEXT NOT NULL DEFAULT '',
      suggestions_json TEXT NOT NULL DEFAULT '[]',
      image_search_json TEXT NOT NULL DEFAULT '{}',
      created_at TEXT NOT NULL
    );
CREATE TABLE article_chat_threads (
      context_key TEXT PRIMARY KEY,
      memory TEXT NOT NULL DEFAULT '',
      updated_at TEXT NOT NULL
    );
CREATE TABLE article_draft_run_events (
        run_id TEXT NOT NULL REFERENCES article_draft_runs(id) ON DELETE CASCADE,
        sequence INTEGER NOT NULL CHECK(sequence > 0),
        kind TEXT NOT NULL CHECK(kind IN ('progress', 'stage_started', 'stage_completed', 'stage_skipped', 'finding_routed', 'authorization_waiting', 'evidence_attached', 'image_curation', 'review_completed', 'checkpoint_updated', 'scope_decision_required', 'completed', 'stopped', 'failed')),
        stage TEXT NOT NULL,
        summary TEXT NOT NULL,
        payload_json TEXT NOT NULL DEFAULT '{}',
        created_at TEXT NOT NULL,
        PRIMARY KEY(run_id, sequence)
      );
CREATE TABLE article_draft_runs (
        id TEXT PRIMARY KEY,
        project_id TEXT NOT NULL REFERENCES content_projects(id) ON DELETE CASCADE,
        status TEXT NOT NULL CHECK(status IN ('running', 'waiting_author', 'passed', 'needs_author', 'failed', 'cancelled')),
        stage TEXT NOT NULL CHECK(stage IN ('planning_depth', 'assessing_practice', 'research_needed', 'awaiting_permission', 'practicing', 'drafting', 'curating_images', 'reviewing', 'revising', 'awaiting_scope_decision', 'passed', 'needs_author', 'failed', 'cancelled')),
        depth_preference TEXT CHECK(depth_preference IS NULL OR depth_preference IN ('concise', 'standard', 'detailed')),
        depth_plan_json TEXT NOT NULL DEFAULT '{}',
        scope_json TEXT NOT NULL DEFAULT '{}',
        outline_revision_sha256 TEXT,
        draft_revision_sha256 TEXT,
        checkpoint_json TEXT NOT NULL DEFAULT '{}',
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      );
CREATE TABLE article_practice_task_events (
        task_id TEXT NOT NULL REFERENCES article_practice_tasks(id) ON DELETE CASCADE,
        sequence INTEGER NOT NULL CHECK(sequence > 0),
        kind TEXT NOT NULL,
        payload_json TEXT NOT NULL,
        created_at TEXT NOT NULL,
        PRIMARY KEY (task_id, sequence)
      );
CREATE TABLE article_practice_tasks (
        id TEXT PRIMARY KEY,
        project_id TEXT NOT NULL REFERENCES content_projects(id) ON DELETE CASCADE,
        status TEXT NOT NULL CHECK(status IN (
          'queued', 'assessing', 'practicing', 'waiting_permission',
          'waiting_feedback', 'waiting_stop_choice', 'drafting',
          'waiting_edit_confirmation', 'waiting_resume_choice',
          'completed', 'completed_with_gaps', 'stopped', 'failed'
        )),
        goal_revision INTEGER NOT NULL DEFAULT 1 CHECK(goal_revision >= 1),
        latest_goal TEXT NOT NULL,
        draft_baseline_hash TEXT,
        waiting_reason TEXT,
        feedback_deadline TEXT,
        resume_status TEXT,
        checkpoint_json TEXT NOT NULL DEFAULT '{}',
        has_gaps INTEGER NOT NULL DEFAULT 0 CHECK(has_gaps IN (0, 1)),
        event_seq INTEGER NOT NULL DEFAULT 0 CHECK(event_seq >= 0),
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      , source_type TEXT NOT NULL DEFAULT 'awen' CHECK(source_type IN ('awen', 'legacy_manual')), legacy_execution_run_id TEXT REFERENCES execution_runs(id) ON DELETE CASCADE);
CREATE TABLE article_quality_checks (
      context_key TEXT PRIMARY KEY,
      ai_check_result TEXT NOT NULL DEFAULT '',
      ai_check_report TEXT NOT NULL DEFAULT '',
      override_reason TEXT NOT NULL DEFAULT '',
      updated_at TEXT NOT NULL
    );
CREATE TABLE article_research_links (
        id TEXT PRIMARY KEY,
        project_id TEXT NOT NULL REFERENCES content_projects(id) ON DELETE CASCADE,
        source_id TEXT NOT NULL REFERENCES content_research_sources(id) ON DELETE CASCADE,
        claim_text TEXT NOT NULL,
        paragraph_sha256 TEXT NOT NULL,
        supporting_excerpt TEXT NOT NULL,
        snapshot_sha256 TEXT NOT NULL,
        status TEXT NOT NULL CHECK(status IN ('pending_author', 'confirmed', 'rejected', 'needs_recheck')),
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      );
CREATE TABLE article_settings (
      context_key TEXT PRIMARY KEY,
      author TEXT NOT NULL DEFAULT '',
      digest TEXT NOT NULL DEFAULT '',
      cover_source TEXT NOT NULL DEFAULT '',
      cover_prompt TEXT NOT NULL DEFAULT '',
      account_id TEXT,
      need_open_comment INTEGER NOT NULL DEFAULT 1,
      only_fans_can_comment INTEGER NOT NULL DEFAULT 0,
      declare_original INTEGER NOT NULL DEFAULT 0,
      enable_reward INTEGER NOT NULL DEFAULT 0,
      is_ai_generated INTEGER NOT NULL DEFAULT 0,
      collection_name TEXT NOT NULL DEFAULT '',
      updated_at TEXT NOT NULL
    );
CREATE TABLE callback_events (
      id TEXT PRIMARY KEY,
      workspace_id TEXT NOT NULL REFERENCES workspaces(id),
      account_id TEXT REFERENCES media_accounts(id),
      event_fingerprint TEXT NOT NULL,
      signature_status TEXT NOT NULL,
      payload_digest TEXT NOT NULL,
      received_at TEXT NOT NULL,
      processed_at TEXT,
      UNIQUE(workspace_id, event_fingerprint)
    );
CREATE TABLE channel_drafts (
      id TEXT PRIMARY KEY,
      workspace_id TEXT NOT NULL REFERENCES workspaces(id),
      account_id TEXT NOT NULL REFERENCES media_accounts(id),
      project_id TEXT REFERENCES content_projects(id),
      source_relative_path TEXT NOT NULL,
      source_hash TEXT NOT NULL,
      generation_mode TEXT NOT NULL DEFAULT 'rewrite' CHECK(generation_mode IN ('rewrite', 'source')),
      title TEXT NOT NULL,
      markdown TEXT NOT NULL,
      author TEXT NOT NULL DEFAULT '',
      digest TEXT NOT NULL DEFAULT '',
      cover_source TEXT NOT NULL DEFAULT '',
      status TEXT NOT NULL CHECK(status IN ('draft', 'approved', 'superseded')),
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    , suggested_category_id TEXT NOT NULL DEFAULT '', suggested_tag_ids TEXT NOT NULL DEFAULT '[]');
CREATE TABLE cnblogs_publish_job_events (
      id TEXT PRIMARY KEY,
      job_id TEXT NOT NULL REFERENCES cnblogs_publish_jobs(id) ON DELETE CASCADE,
      previous_status TEXT,
      new_status TEXT NOT NULL,
      source TEXT NOT NULL,
      reason TEXT,
      created_at TEXT NOT NULL
    );
CREATE TABLE cnblogs_publish_jobs (
      id TEXT PRIMARY KEY,
      workspace_id TEXT NOT NULL REFERENCES workspaces(id),
      account_id TEXT NOT NULL REFERENCES media_accounts(id),
      channel_draft_id TEXT NOT NULL REFERENCES channel_drafts(id),
      rendered_package_hash TEXT NOT NULL,
      idempotency_key TEXT NOT NULL UNIQUE,
      status TEXT NOT NULL CHECK (status IN (
        'queued', 'draft_creating', 'draft_created', 'confirming',
        'published', 'failed', 'needs_manual_reconciliation', 'cancelled',
        'needs_credentials'
      )),
      remote_url TEXT,
      remote_content_id TEXT,
      status_note TEXT,
      error_message TEXT,
      status_source TEXT NOT NULL DEFAULT 'system' CHECK (status_source IN ('system', 'manual')),
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE content_briefs (
      project_id TEXT PRIMARY KEY REFERENCES content_projects(id) ON DELETE CASCADE,
      topic TEXT NOT NULL DEFAULT '',
      objective TEXT NOT NULL DEFAULT '',
      audience TEXT NOT NULL DEFAULT '',
      angle TEXT NOT NULL DEFAULT '',
      source_notes TEXT NOT NULL DEFAULT '',
      draft_depth_preference TEXT CHECK(draft_depth_preference IS NULL OR draft_depth_preference IN ('concise', 'standard', 'detailed')),
      updated_at TEXT NOT NULL
    );
CREATE TABLE content_drafts (
      project_id TEXT PRIMARY KEY REFERENCES content_projects(id) ON DELETE CASCADE,
      markdown TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE "content_generation_reviews" (
        id TEXT PRIMARY KEY,
        project_id TEXT NOT NULL REFERENCES content_projects(id) ON DELETE CASCADE,
        artifact_type TEXT NOT NULL CHECK(artifact_type IN ('outline', 'draft', 'channel_draft_csdn', 'channel_draft_cnblogs', 'channel_draft_juejin', 'channel_draft_51cto')),
        revision_sha256 TEXT NOT NULL,
        status TEXT NOT NULL CHECK(status IN ('passed', 'needs_author', 'review_failed')),
        repair_rounds INTEGER NOT NULL CHECK(repair_rounds BETWEEN 0 AND 5),
        report_json TEXT NOT NULL,
        created_at TEXT NOT NULL
      );
CREATE TABLE content_outline_drafts (
      project_id TEXT PRIMARY KEY REFERENCES content_projects(id) ON DELETE CASCADE,
      markdown TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE content_outlines (
      project_id TEXT PRIMARY KEY REFERENCES content_projects(id) ON DELETE CASCADE,
      markdown TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE content_practice_plans (
      project_id TEXT PRIMARY KEY REFERENCES content_projects(id) ON DELETE CASCADE,
      markdown TEXT NOT NULL,
      status TEXT NOT NULL CHECK(status IN ('draft', 'confirmed', 'skipped')),
      updated_at TEXT NOT NULL
    );
CREATE TABLE content_projects (
      id TEXT PRIMARY KEY,
      workspace_id TEXT NOT NULL REFERENCES workspaces(id),
      target_account_id TEXT REFERENCES media_accounts(id),
      topic TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'idea',
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    , source_relative_path TEXT, practice_project_directory TEXT);
CREATE TABLE content_research_plan_states (
      project_id TEXT PRIMARY KEY REFERENCES content_projects(id) ON DELETE CASCADE,
      state_json TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE content_research_plans (
      project_id TEXT PRIMARY KEY REFERENCES content_projects(id) ON DELETE CASCADE,
      plan_markdown TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE content_research_sources (
      id TEXT PRIMARY KEY,
      project_id TEXT NOT NULL REFERENCES content_projects(id) ON DELETE CASCADE,
      title TEXT NOT NULL,
      url TEXT NOT NULL,
      excerpt TEXT NOT NULL DEFAULT '',
      claims_json TEXT NOT NULL DEFAULT '[]',
      provenance_json TEXT NOT NULL DEFAULT '{}',
      evidence_json TEXT NOT NULL DEFAULT '{}',
      adoption_history_json TEXT NOT NULL DEFAULT '[]',
      adoption_status TEXT NOT NULL DEFAULT 'recommended' CHECK(adoption_status IN ('recommended', 'adopted', 'rejected', 'pending_verification')),
      source_type TEXT NOT NULL CHECK(source_type IN ('official', 'public')),
      retrieved_at TEXT NOT NULL,
      selected INTEGER NOT NULL DEFAULT 1
    );
CREATE TABLE content_reviews (
      project_id TEXT PRIMARY KEY REFERENCES content_projects(id) ON DELETE CASCADE,
      status TEXT NOT NULL DEFAULT 'pending',
      fact_checked INTEGER NOT NULL DEFAULT 0,
      account_fit_checked INTEGER NOT NULL DEFAULT 0,
      ai_check_result TEXT NOT NULL DEFAULT '',
      notes TEXT NOT NULL DEFAULT '',
      updated_at TEXT NOT NULL
    );
CREATE TABLE content_sources (
      workspace_id TEXT PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE,
      root_path TEXT NOT NULL,
      source_type TEXT NOT NULL DEFAULT 'vitepress',
      pattern_json TEXT NOT NULL DEFAULT '',
      updated_at TEXT NOT NULL
    );
CREATE TABLE content_specified_sources (
      id TEXT PRIMARY KEY,
      project_id TEXT NOT NULL REFERENCES content_projects(id) ON DELETE CASCADE,
      url TEXT NOT NULL,
      status TEXT NOT NULL CHECK(status IN ('pending_manual_verification', 'verified', 'rejected', 'failed')),
      verification_note TEXT NOT NULL DEFAULT '',
      failure_reason TEXT NOT NULL DEFAULT '',
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      UNIQUE(project_id, url)
    );
CREATE TABLE credential_secrets (
      id TEXT PRIMARY KEY,
      encrypted_value BLOB NOT NULL,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE csdn_publish_job_events (
      id TEXT PRIMARY KEY,
      job_id TEXT NOT NULL REFERENCES csdn_publish_jobs(id) ON DELETE CASCADE,
      previous_status TEXT NOT NULL,
      new_status TEXT NOT NULL,
      source TEXT NOT NULL,
      reason TEXT NOT NULL,
      created_at TEXT NOT NULL
    );
CREATE TABLE csdn_publish_jobs (
      id TEXT PRIMARY KEY,
      workspace_id TEXT NOT NULL REFERENCES workspaces(id),
      account_id TEXT NOT NULL REFERENCES media_accounts(id),
      channel_draft_id TEXT NOT NULL REFERENCES channel_drafts(id),
      rendered_package_hash TEXT NOT NULL,
      idempotency_key TEXT NOT NULL UNIQUE,
      status TEXT NOT NULL CHECK(status IN (
        'queued', 'needs_login', 'filling', 'ready_for_final_confirmation',
        'submitting', 'published', 'needs_manual_reconciliation',
        'needs_user', 'failed_before_submit', 'failed', 'cancelled'
      )),
      remote_url TEXT,
      remote_content_id TEXT,
      status_note TEXT,
      error_message TEXT,
      status_source TEXT NOT NULL DEFAULT 'system',
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE execution_artifacts (
      id TEXT PRIMARY KEY,
      run_id TEXT NOT NULL REFERENCES execution_runs(id) ON DELETE CASCADE,
      relative_path TEXT NOT NULL,
      size_bytes INTEGER NOT NULL,
      sha256 TEXT NOT NULL,
      created_at TEXT NOT NULL
    );
CREATE TABLE execution_runs (
      id TEXT PRIMARY KEY,
      project_id TEXT REFERENCES content_projects(id) ON DELETE SET NULL,
      request_json TEXT NOT NULL,
      preflight_json TEXT NOT NULL,
      status TEXT NOT NULL,
      exit_code INTEGER,
      signal TEXT,
      stdout TEXT NOT NULL DEFAULT '',
      stderr TEXT NOT NULL DEFAULT '',
      truncated INTEGER NOT NULL DEFAULT 0,
      error_message TEXT NOT NULL DEFAULT '',
      created_at TEXT NOT NULL,
      started_at TEXT,
      finished_at TEXT
    );
CREATE TABLE experimental_observations (
      id TEXT PRIMARY KEY,
      project_id TEXT NOT NULL REFERENCES content_projects(id) ON DELETE CASCADE,
      execution_run_id TEXT NOT NULL UNIQUE REFERENCES execution_runs(id) ON DELETE CASCADE,
      title TEXT NOT NULL,
      claim TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'accepted', 'rejected')),
      provenance_json TEXT NOT NULL DEFAULT '{}',
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE fiftyone_cto_publish_job_events (
      id TEXT PRIMARY KEY,
      job_id TEXT NOT NULL REFERENCES fiftyone_cto_publish_jobs(id) ON DELETE CASCADE,
      previous_status TEXT,
      new_status TEXT NOT NULL,
      source TEXT NOT NULL,
      reason TEXT,
      created_at TEXT NOT NULL
    );
CREATE TABLE fiftyone_cto_publish_jobs (
      id TEXT PRIMARY KEY,
      workspace_id TEXT NOT NULL REFERENCES workspaces(id),
      account_id TEXT NOT NULL REFERENCES media_accounts(id),
      channel_draft_id TEXT NOT NULL REFERENCES channel_drafts(id),
      rendered_package_hash TEXT NOT NULL,
      idempotency_key TEXT NOT NULL UNIQUE,
      status TEXT NOT NULL CHECK (status IN (
        'queued', 'draft_creating', 'draft_created', 'confirming',
        'published', 'failed', 'needs_manual_reconciliation', 'cancelled',
        'needs_credentials'
      )),
      remote_url TEXT,
      remote_content_id TEXT,
      status_note TEXT,
      error_message TEXT,
      status_source TEXT NOT NULL DEFAULT 'system' CHECK (status_source IN ('system', 'manual')),
      -- 发布时的发布参数（pid/cate_id/tags/blog_type）：上次发布用的分类/标签/类型，
      -- 再次进入渠道稿时从这里恢复，避免每次发布都要重新选。pid 与 cate_id 是 51CTO
      -- 后端的不可变 id，不是分类显示文案。
      pid TEXT,
      cate_id TEXT,
      tags TEXT,
      blog_type TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE image_search_history (
      id TEXT PRIMARY KEY,
      context_key TEXT NOT NULL,
      query TEXT NOT NULL,
      provider TEXT,
      items_json TEXT NOT NULL,
      created_at TEXT NOT NULL
    );
CREATE TABLE juejin_publish_job_events (
      id TEXT PRIMARY KEY,
      job_id TEXT NOT NULL REFERENCES juejin_publish_jobs(id) ON DELETE CASCADE,
      previous_status TEXT,
      new_status TEXT NOT NULL,
      source TEXT NOT NULL,
      reason TEXT,
      created_at TEXT NOT NULL
    );
CREATE TABLE juejin_publish_jobs (
      id TEXT PRIMARY KEY,
      workspace_id TEXT NOT NULL REFERENCES workspaces(id),
      account_id TEXT NOT NULL REFERENCES media_accounts(id),
      channel_draft_id TEXT NOT NULL REFERENCES channel_drafts(id),
      rendered_package_hash TEXT NOT NULL,
      idempotency_key TEXT NOT NULL UNIQUE,
      status TEXT NOT NULL CHECK (status IN (
        'queued', 'draft_creating', 'draft_created', 'confirming',
        'published', 'failed', 'needs_manual_reconciliation', 'cancelled',
        'needs_credentials'
      )),
      remote_url TEXT,
      remote_content_id TEXT,
      status_note TEXT,
      error_message TEXT,
      status_source TEXT NOT NULL DEFAULT 'system' CHECK (status_source IN ('system', 'manual')),
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE media_accounts (
      id TEXT PRIMARY KEY,
      workspace_id TEXT NOT NULL REFERENCES workspaces(id),
      platform TEXT NOT NULL,
      display_name TEXT NOT NULL,
      external_account_id TEXT,
      capability_level TEXT NOT NULL DEFAULT 'unverified',
      credential_ref TEXT,
      created_at TEXT NOT NULL, deleted_at TEXT,
      UNIQUE(workspace_id, platform, external_account_id)
    );
CREATE TABLE memory_candidates (
      id TEXT PRIMARY KEY,
      scope_key TEXT NOT NULL,
      kind TEXT NOT NULL,
      content TEXT NOT NULL,
      content_hash TEXT NOT NULL,
      source_event_ids_json TEXT NOT NULL DEFAULT '[]',
      status TEXT NOT NULL DEFAULT 'candidate',
      support_count INTEGER NOT NULL DEFAULT 1,
      confidence REAL NOT NULL DEFAULT 0,
      importance REAL NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      expires_at TEXT,
      promoted_memory_id TEXT
    );
CREATE TABLE memory_maintenance_state (
      scope_key TEXT PRIMARY KEY,
      watermark TEXT,
      status TEXT NOT NULL DEFAULT 'idle',
      updated_at TEXT NOT NULL,
      last_error TEXT NOT NULL DEFAULT ''
    );
CREATE TABLE memory_uses (
      id TEXT PRIMARY KEY,
      memory_id TEXT NOT NULL REFERENCES agent_memories(id) ON DELETE CASCADE,
      task_key TEXT NOT NULL,
      created_at TEXT NOT NULL
    );
CREATE TABLE model_connections (
      provider TEXT PRIMARY KEY,
      display_name TEXT NOT NULL,
      model_id TEXT NOT NULL DEFAULT '',
      base_url TEXT NOT NULL DEFAULT '',
      proxy_url TEXT NOT NULL DEFAULT '',
      enabled INTEGER NOT NULL DEFAULT 1,
      built_in_search INTEGER NOT NULL DEFAULT 1,
      custom INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE outbox_jobs (
      id TEXT PRIMARY KEY,
      workspace_id TEXT NOT NULL REFERENCES workspaces(id),
      job_type TEXT NOT NULL,
      business_key TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'pending',
      available_at TEXT NOT NULL,
      lease_until TEXT,
      attempts INTEGER NOT NULL DEFAULT 0,
      payload_json TEXT NOT NULL,
      created_at TEXT NOT NULL,
      UNIQUE(workspace_id, job_type, business_key)
    );
CREATE TABLE publish_lifecycle_events (
      id TEXT PRIMARY KEY,
      job_id TEXT NOT NULL REFERENCES publish_lifecycle_jobs(id) ON DELETE CASCADE,
      previous_status TEXT NOT NULL,
      new_status TEXT NOT NULL,
      source TEXT NOT NULL,
      reason TEXT NOT NULL,
      created_at TEXT NOT NULL
    );
CREATE TABLE publish_lifecycle_jobs (
      id TEXT PRIMARY KEY,
      platform TEXT NOT NULL,
      platform_job_id TEXT NOT NULL UNIQUE,
      workspace_id TEXT NOT NULL REFERENCES workspaces(id),
      account_id TEXT NOT NULL REFERENCES media_accounts(id),
      channel_draft_id TEXT NOT NULL REFERENCES channel_drafts(id),
      rendered_package_hash TEXT NOT NULL,
      idempotency_key TEXT NOT NULL UNIQUE,
      status TEXT NOT NULL CHECK(status IN (
        'queued', 'preparing', 'waiting_user', 'ready', 'submitting',
        'published', 'needs_credentials', 'failed',
        'needs_manual_reconciliation', 'cancelled'
      )),
      remote_url TEXT,
      remote_content_id TEXT,
      status_note TEXT,
      error_message TEXT,
      status_source TEXT NOT NULL DEFAULT 'system' CHECK(status_source IN ('system', 'manual', 'legacy_sync')),
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE research_runs (
      id TEXT PRIMARY KEY,
      project_id TEXT NOT NULL REFERENCES content_projects(id) ON DELETE CASCADE,
      task_id TEXT NOT NULL UNIQUE REFERENCES research_tasks(id) ON DELETE CASCADE,
      kind TEXT NOT NULL CHECK(kind IN ('generate', 'follow_up', 'refresh')),
      plan_markdown TEXT NOT NULL,
      plan_json TEXT NOT NULL DEFAULT '{}',
      sources_json TEXT NOT NULL DEFAULT '[]',
      specified_sources_json TEXT NOT NULL DEFAULT '[]',
      created_at TEXT NOT NULL
    );
CREATE TABLE research_task_events (
      id TEXT PRIMARY KEY,
      task_id TEXT NOT NULL REFERENCES research_tasks(id) ON DELETE CASCADE,
      event_type TEXT NOT NULL,
      payload_json TEXT NOT NULL DEFAULT '{}',
      created_at TEXT NOT NULL
    );
CREATE TABLE research_tasks (
      id TEXT PRIMARY KEY,
      project_id TEXT NOT NULL REFERENCES content_projects(id) ON DELETE CASCADE,
      kind TEXT NOT NULL CHECK(kind IN ('generate', 'follow_up')),
      request_hash TEXT NOT NULL,
      request_json TEXT NOT NULL DEFAULT '{}',
      status TEXT NOT NULL CHECK(status IN ('queued', 'running', 'waiting_user', 'paused', 'completed', 'completed_with_warnings', 'failed', 'cancelled')),
      result_state TEXT NOT NULL DEFAULT 'proposed',
      current_step_id TEXT,
      cancel_requested INTEGER NOT NULL DEFAULT 0,
      attempt INTEGER NOT NULL DEFAULT 1,
      last_checkpoint TEXT NOT NULL DEFAULT '',
      last_error TEXT NOT NULL DEFAULT '',
      archived_at TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL,
      last_heartbeat_at TEXT NOT NULL
    );
CREATE TABLE schema_migrations (
      version INTEGER PRIMARY KEY,
      applied_at TEXT NOT NULL
    );
CREATE TABLE skill_settings (
      skill_id TEXT PRIMARY KEY,
      enabled INTEGER NOT NULL DEFAULT 1,
      provider TEXT,
      updated_at TEXT NOT NULL
    );
CREATE TABLE wechat_collections (
      account_id TEXT NOT NULL REFERENCES media_accounts(id) ON DELETE CASCADE,
      name TEXT NOT NULL,
      wechat_collection_id TEXT,
      observed_at TEXT NOT NULL,
      PRIMARY KEY (account_id, name)
    );
CREATE TABLE wechat_publish_job_events (
      id TEXT PRIMARY KEY,
      job_id TEXT NOT NULL REFERENCES wechat_publish_jobs(id),
      previous_status TEXT NOT NULL,
      new_status TEXT NOT NULL,
      source TEXT NOT NULL,
      reason TEXT NOT NULL,
      created_at TEXT NOT NULL
    );
CREATE TABLE wechat_publish_jobs (
      id TEXT PRIMARY KEY,
      workspace_id TEXT NOT NULL REFERENCES workspaces(id),
      account_id TEXT NOT NULL REFERENCES media_accounts(id),
      project_id TEXT REFERENCES content_projects(id),
      source_relative_path TEXT,
      mode TEXT NOT NULL,
      title TEXT NOT NULL,
      draft_media_id TEXT,
      publish_id TEXT,
      message_id TEXT,
      status TEXT NOT NULL,
      error_message TEXT,
      status_source TEXT NOT NULL DEFAULT 'system',
      status_note TEXT,
      declare_original INTEGER NOT NULL DEFAULT 0,
      enable_reward INTEGER NOT NULL DEFAULT 0,
      is_ai_generated INTEGER NOT NULL DEFAULT 0,
      collection_name TEXT NOT NULL DEFAULT '',
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
CREATE TABLE workspaces (
      id TEXT PRIMARY KEY,
      display_name TEXT NOT NULL,
      timezone TEXT NOT NULL DEFAULT 'Asia/Shanghai',
      created_at TEXT NOT NULL
    );
CREATE TABLE writing_memories (
      scope_key TEXT PRIMARY KEY,
      memory TEXT NOT NULL DEFAULT '',
      updated_at TEXT NOT NULL
    );
